void moveZeroes(int *nums, int numsSize) {
  int i = -1;
  int j = 0;
  while (j <= numsSize - 1) {
    if (nums[j] != 0) {
      i++;
      nums[i] = nums[j];
    }
    j++;
  }
  for (int m = i + 1; m < numsSize; m++) {
    nums[m] = 0;
  }
}

class Solution {
public:
  void moveZeroes(vector<int> &nums) {
    int n = nums.size(), left = 0, right = 0;
    while (right < n) {
      if (nums[right]) {
        swap(nums[left], nums[right]);
        left++;
      }
      right++;
    }
  }
};
